body.script:
document.addEventListener('click', function (e) {
  if (e.target.closest) { if (e.target.closest('a, .nuit-badge')) { return; } }
  var c = e.target.closest ? e.target.closest('.mcard, .card, .dcard') : null;
  if (!c) { return; }
  if (!c.dataset.client) { return; }
  if (c.dataset.annexe === '1') {
    var td2 = c.closest('[data-day]');
    var ctx2 = document.getElementById('pctx');
    var off2 = parseInt(ctx2.dataset.off);
    document.getElementById('am-id').value = c.dataset.id;
    document.getElementById('am-date').value = td2 ? td2.dataset.day : ctx2.dataset.today;
    document.getElementById('am-op').value = td2 ? (td2.dataset.res || '0') : '0';
    document.getElementById('am-note').value = c.dataset.note || '';
    if (c.dataset.start) { document.getElementById('am-h1').value = locHM(c.dataset.start, off2); }
    if (c.dataset.end) { document.getElementById('am-h2').value = locHM(c.dataset.end, off2); }
    document.getElementById('am-title').textContent = 'Modifier la tâche';
    document.getElementById('am-del').style.display = '';
    var ar = document.getElementById('am-rapport');
    if (ar) { ar.style.display = (c.dataset.fdt ? '' : 'none'); if (c.dataset.fdt) { ar.href = '/report/pdf/protec_custom.report_fiche_fin_travaux/' + c.dataset.id + '?context=%7B%22allowed_company_ids%22%3A%5B2%5D%7D'; } }
    document.getElementById('amodal').classList.add('open');
    return;
  }
  var ds = c.dataset;
  function setrow(rowId, spanId, val) {
    var row = document.getElementById(rowId);
    if (val) { row.style.display = ''; document.getElementById(spanId).textContent = val; }
    else { row.style.display = 'none'; }
  }
  document.getElementById('pm-client').textContent = ds.client;
  document.getElementById('pm-time').textContent = ds.time;
  document.getElementById('pm-adresse').textContent = ds.adresse || '—';
  setrow('pm-r-inter', 'pm-inter', ds.inter);
  setrow('pm-r-lieu', 'pm-lieu', ds.lieu);
  setrow('pm-r-objet', 'pm-objet', ds.objet);
  setrow('pm-r-camion', 'pm-camion', ds.camion);
  var telRow = document.getElementById('pm-r-tel');
  if (ds.tel) {
    telRow.style.display = '';
    var a = document.getElementById('pm-tel');
    a.textContent = ds.tel; a.href = 'tel:' + ds.tel.replace(/ /g, '');
  } else { telRow.style.display = 'none'; }
  document.getElementById('pm-ref').textContent = ds.ref || '—';
  document.getElementById('pm-fdt').style.display = ds.fdt ? '' : 'none';
  var rp = document.getElementById('pm-rapport');
  if (rp) { rp.style.display = 'none'; if (ds.fdt) { if (ds.id) { rp.style.display = ''; rp.href = '/report/pdf/protec_custom.report_fiche_fin_travaux/' + ds.id + '?context=%7B%22allowed_company_ids%22%3A%5B2%5D%7D'; } } }
  var so = document.getElementById('pm-so');
  if (ds.so) { so.style.display = ''; so.href = ds.so; } else { so.style.display = 'none'; }
  document.getElementById('pmodal').classList.add('open');
});
document.getElementById('pmodal').addEventListener('click', function (e) {
  if (e.target.id === 'pmodal') { e.target.classList.remove('open'); }
});

var pdrag = null;
function pad2(n) { return ('0' + n).slice(-2); }
function shiftUTC(str, days) {
  var d = new Date(str.replace(' ', 'T') + 'Z');
  d = new Date(d.getTime() + days * 86400000);
  return d.getUTCFullYear() + '-' + pad2(d.getUTCMonth() + 1) + '-' + pad2(d.getUTCDate())
    + ' ' + pad2(d.getUTCHours()) + ':' + pad2(d.getUTCMinutes()) + ':' + pad2(d.getUTCSeconds());
}
function dropTarget(e) {
  var el = e.target;
  while (el) {
    if (el.dataset) { if (el.dataset.day !== undefined) { if (el.dataset.emp !== undefined) { return el; } } }
    el = el.parentElement;
  }
  return null;
}
document.addEventListener('dragstart', function (e) {
  var c = e.target.closest ? e.target.closest('[draggable]') : null;
  if (!c) { return; }
  var td = dropTarget(e);
  if (!td) { return; }
  if (e.dataTransfer) {
    e.dataTransfer.setData('text/plain', c.dataset.id || 'x');
    e.dataTransfer.effectAllowed = 'move';
  }
  pdrag = { id: parseInt(c.dataset.id), start: c.dataset.start, end: c.dataset.end,
            day: td.dataset.day, emp: parseInt(td.dataset.emp), res: parseInt(td.dataset.res || 0) };
  c.classList.add('dragging');
});
document.addEventListener('dragend', function () {
  document.querySelectorAll('.dragging').forEach(function (el) { el.classList.remove('dragging'); });
  document.querySelectorAll('.drop-ok').forEach(function (el) { el.classList.remove('drop-ok'); });
});
document.addEventListener('dragover', function (e) {
  var td = dropTarget(e);
  if (td) { if (pdrag) {
    e.preventDefault();
    if (e.dataTransfer) { e.dataTransfer.dropEffect = 'move'; }
    td.classList.add('drop-ok');
  } }
});
document.addEventListener('dragleave', function (e) {
  var td = dropTarget(e);
  if (td) { td.classList.remove('drop-ok'); }
});
document.addEventListener('drop', function (e) {
  var td = dropTarget(e);
  if (!td) { return; }
  if (!pdrag) { return; }
  e.preventDefault();
  td.classList.remove('drop-ok');
  var dayDelta = Math.round((new Date(td.dataset.day) - new Date(pdrag.day)) / 86400000);
  var newEmp = parseInt(td.dataset.emp);
  var newRes = parseInt(td.dataset.res || 0);
  var vals = {};
  if (dayDelta !== 0) {
    vals.start_datetime = shiftUTC(pdrag.start, dayDelta);
    if (pdrag.end) { vals.end_datetime = shiftUTC(pdrag.end, dayDelta); }
  }
  if (newEmp !== pdrag.emp) {
    if (newRes) { vals.resource_ids = [[6, 0, [newRes]]]; } else { vals.resource_ids = [[5]]; }
  }
  if (Object.keys(vals).length === 0) { pdrag = null; return; }
  fetch('/web/dataset/call_kw/planning.slot/write', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    credentials: 'same-origin',
    body: JSON.stringify({ jsonrpc: '2.0', method: 'call',
      params: { model: 'planning.slot', method: 'write',
                args: [[pdrag.id], vals], kwargs: {} } })
  }).then(function (r) { return r.json(); }).then(function (d) {
    if (d.error) {
      alert('Modification refusée — connectez-vous à Odoo dans cet onglet pour déplacer les interventions.');
    } else { location.reload(); }
  }).catch(function () { alert('Erreur réseau'); });
  pdrag = null;
});
function fmtUTC(d) {
  return d.getUTCFullYear() + '-' + pad2(d.getUTCMonth() + 1) + '-' + pad2(d.getUTCDate())
    + ' ' + pad2(d.getUTCHours()) + ':' + pad2(d.getUTCMinutes()) + ':' + pad2(d.getUTCSeconds());
}
function locHM(utcStr, off) {
  var d = new Date(new Date(utcStr.replace(' ', 'T') + 'Z').getTime() + off * 3600000);
  return pad2(d.getUTCHours()) + ':' + pad2(d.getUTCMinutes());
}
function mkUTC(dayIso, hhmm, off) {
  var dp = dayIso.split('-');
  var tp = hhmm.split(':');
  var ms = Date.UTC(parseInt(dp[0]), parseInt(dp[1]) - 1, parseInt(dp[2]),
                    parseInt(tp[0]), parseInt(tp[1])) - off * 3600000;
  return fmtUTC(new Date(ms));
}
document.addEventListener('dblclick', function (e) {
  if (e.target.closest) { if (e.target.closest('.card, .dcard, .mcard, a, button, input, select')) { return; } }
  var td = dropTarget(e);
  if (!td) { return; }
  document.getElementById('am-date').value = td.dataset.day;
  document.getElementById('am-op').value = td.dataset.res || '0';
  document.getElementById('am-note').value = '';
  document.getElementById('am-id').value = '';
  document.getElementById('am-title').textContent = 'Nouvelle tâche';
  document.getElementById('am-del').style.display = 'none'; var ar2 = document.getElementById('am-rapport'); if (ar2) { ar2.style.display = 'none'; }
  document.getElementById('amodal').classList.add('open');
});
document.getElementById('am-del').addEventListener('click', function (ev) {
  ev.preventDefault();
  var editId = document.getElementById('am-id').value;
  if (!editId) { return; }
  if (!confirm('Supprimer cette tâche ?')) { return; }
  fetch('/web/dataset/call_kw/planning.slot/unlink', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    credentials: 'same-origin',
    body: JSON.stringify({ jsonrpc: '2.0', method: 'call',
      params: { model: 'planning.slot', method: 'unlink', args: [[parseInt(editId)]], kwargs: {} } })
  }).then(function (r) { return r.json(); }).then(function (d) {
    if (d.error) { alert('Suppression refusée — connectez-vous à Odoo.'); }
    else { location.reload(); }
  }).catch(function () { alert('Erreur réseau'); });
});
var bat = document.getElementById('btn-addtask');
if (bat) {
  bat.addEventListener('click', function (ev) {
    ev.preventDefault();
    var ctx = document.getElementById('pctx');
    document.getElementById('am-date').value = ctx.dataset.today;
    document.getElementById('am-op').value = '0';
    document.getElementById('am-note').value = '';
    document.getElementById('am-id').value = '';
    document.getElementById('am-title').textContent = 'Nouvelle tâche';
    document.getElementById('am-del').style.display = 'none'; var ar2 = document.getElementById('am-rapport'); if (ar2) { ar2.style.display = 'none'; }
    document.getElementById('amodal').classList.add('open');
  });
}
document.getElementById('amodal').addEventListener('click', function (e) {
  if (e.target.id === 'amodal') { e.target.classList.remove('open'); }
});
document.getElementById('am-save').addEventListener('click', function (ev) {
  ev.preventDefault();
  var note = document.getElementById('am-note').value.trim();
  if (!note) { alert('La note est obligatoire'); return; }
  var ctx = document.getElementById('pctx');
  var off = parseInt(ctx.dataset.off);
  var cid = parseInt(ctx.dataset.cid);
  var day = document.getElementById('am-date').value;
  if (!day) { alert('Choisissez un jour'); return; }
  var res = parseInt(document.getElementById('am-op').value);
  var h1 = document.getElementById('am-h1').value || '08:00';
  var h2 = document.getElementById('am-h2').value || '09:00';
  var editId = document.getElementById('am-id').value;
  var vals = { name: note, start_datetime: mkUTC(day, h1, off),
               end_datetime: mkUTC(day, h2, off) };
  if (!editId) { vals.company_id = cid; }
  if (res) { vals.resource_ids = [[6, 0, [res]]]; } else { vals.resource_ids = [[5]]; }
  var meth = editId ? 'write' : 'create';
  var args = editId ? [[parseInt(editId)], vals] : [vals];
  fetch('/web/dataset/call_kw/planning.slot/' + meth, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    credentials: 'same-origin',
    body: JSON.stringify({ jsonrpc: '2.0', method: 'call',
      params: { model: 'planning.slot', method: meth, args: args, kwargs: {} } })
  }).then(function (r) { return r.json(); }).then(function (d) {
    if (d.error) {
      alert('Création refusée — connectez-vous à Odoo dans cet onglet.');
    } else { location.reload(); }
  }).catch(function () { alert('Erreur réseau'); });
});
document.addEventListener('click', function (e) {
  var b = e.target.closest ? e.target.closest('.nuit-badge') : null;
  if (!b) { return; }
  e.preventDefault();
  var c = b.closest('[data-id]');
  if (!c) { return; }
  var newVal = b.dataset.etale !== '1';
  fetch('/web/dataset/call_kw/planning.slot/write', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    credentials: 'same-origin',
    body: JSON.stringify({ jsonrpc: '2.0', method: 'call',
      params: { model: 'planning.slot', method: 'write',
                args: [[parseInt(c.dataset.id)], { x_nuit_etale: newVal }], kwargs: {} } })
  }).then(function (r) { return r.json(); }).then(function (d) {
    if (d.error) {
      alert('Modification refusée — connectez-vous à Odoo dans cet onglet.');
    } else { location.reload(); }
  }).catch(function () { alert('Erreur réseau'); });
});
function naToggle() {
  var el = document.getElementById('na-chips');
  var btn = document.getElementById('na-hide-btn');
  if (!el) { return; }
  var hide = el.style.display !== 'none';
  el.style.display = hide ? 'none' : '';
  if (btn) { btn.textContent = hide ? 'Afficher' : 'Masquer'; }
  localStorage.setItem('naHide', hide ? '1' : '0');
}
var ncInit = document.getElementById('na-chips');
if (ncInit) {
  if (localStorage.getItem('naHide') === '1') {
    ncInit.style.display = 'none';
    var nbInit = document.getElementById('na-hide-btn');
    if (nbInit) { nbInit.textContent = 'Afficher'; }
  }
}
var clf = document.getElementById('clfilter');
if (clf) {
  clf.addEventListener('input', function () {
    var q = clf.value.toLowerCase();
    document.querySelectorAll('[data-client]').forEach(function (el) {
      var show = true;
      if (q) { show = (el.dataset.client || '').toLowerCase().indexOf(q) !== -1; }
      el.style.display = show ? '' : 'none';
    });
  });
}
fetch('/web/session/get_session_info', { method: 'POST',
  headers: { 'Content-Type': 'application/json' }, credentials: 'same-origin',
  body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: {} })
}).then(function (r) { return r.json(); }).then(function (d) {
  var u = d.result ? d.result.uid : null;
  if (!u) { var b = document.getElementById('ro-banner'); if (b) { b.style.display = 'block'; } }
}).catch(function () {});
